                  Frees.push_back(FI);
                  if (DomLabel)
                    CleanupFrees[DomLabel].push_back(VD);
                }
              }
            }
          }
          return true;
        }

        const LabelDecl *findDominatingLabel(SourceLocation Loc) const {
          // Find label with largest location that is before Loc.
          const LabelDecl *Best = nullptr;
