      private:
        ASTContext &Ctx;
        const SourceManager &SM;
      }; // BodyScanner

      // Helper comparisons on source locations
      static bool isBefore(const SourceManager &SM, SourceLocation A, SourceLocation B) {
        return SM.isBeforeInTranslationUnit(A, B);
