        ProgramStateRef State = C.getState();
        const MemRegion *MR = Call.getReturnValue().getAsRegion();
        if (!MR)
          return;
        MR = MR->getBaseRegion();
        if (!MR)
          return;

        State = State->remove<UninitBufMap>(MR);

        uint64_t Nmemb = 0, Sz = 0;
        if (getArgConstUInt(Call, NmembIdx, C, Nmemb) &&
